public class StageBuilderQA{static int n;interface E{void run()throws Exception;}static void ok(boolean b){if(!b)throw new AssertionError();n++;}static void no(E e)throws Exception{try{e.run();throw new AssertionError();}catch(IllegalArgumentException|IllegalStateException|IOException good){n++;}}
 public static void main(String[]a)throws Exception{NonFlightIntentFence<String>f=new NonFlightIntentFence<>(200,16);f.enqueue("stage1","STAGE_BINDING","payload",1);ok(f.consume(2,false)==null);NonFlightIntentFence.Ticket<String>t=f.consume(3,true);ok(t.action.equals("STAGE_BINDING")&&t.payload.equals("payload")&&t.receivedNs==1);ok(f.consume(4,true)==null);no(()->f.enqueue("stage1","STAGE_BINDING","p",5));f.enqueue("stage2","STAGE_BINDING","p",6);ok(f.consume(207,true)==null);f.enqueue("stage3","STAGE_BINDING","p",208);f.cancel("HISTORY");ok(f.consume(209,true)==null);for(String action:new String[]{"CONNECT","ARM","GUIDED","TAKEOFF","LAND","CONSENT","PULSE"})no(()->f.enqueue("bad-"+action,action,"p",210));long clock=211;for(String action:new String[]{"CLOSE","STATUS"}){f.enqueue("ok-"+action,action,"p",clock++);ok(f.consume(clock++,true).action.equals(action));}byte[]bytes="bound-observation".getBytes();ok(NonFlightIntentFence.verifyBindingSHA(bytes,Values.hash(bytes)).equals(Values.hash(bytes)));no(()->NonFlightIntentFence.verifyBindingSHA(bytes,"0".repeat(64)));no(()->NonFlightIntentFence.verifyBindingSHA(bytes,null));no(()->f.enqueue("clock","STAGE_BINDING","p",200));System.out.println("PASS "+n+" stage-fence assertions, zero writer API present");}}
